using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private readonly Uri baseAddress;
    private int status = 200;
    private string responseBody = """{"status":"approved"}""";
    private string? method, path, contentType, requestBody;

    public HttpPaymentGatewayTests()
    {
        var port = GetFreePort();
        baseAddress = new Uri($"http://127.0.0.1:{port}");
        listener.Prefixes.Add($"{baseAddress}");
        listener.Start();
        _ = Task.Run(Serve);
        client = new HttpClient { BaseAddress = baseAddress };
    }

    [Fact]
    public async Task The_request_sent_to_the_provider_has_the_expected_shape()
    {
        await new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", new Money(12.5m, "eur"), CancellationToken.None);

        Assert.Equal("POST", method);
        Assert.Equal("/v1/authorizations", path);
        Assert.StartsWith("application/json", contentType);
        using var json = JsonDocument.Parse(requestBody!);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.5m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        responseBody = """{"status":"declined"}""";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_refusal_with_402_is_read_as_declined()
    {
        status = 402;
        responseBody = """{"error":"card_refused"}""";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData("""{"state":"approved"}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("null")]
    public async Task An_unrecognised_answer_is_never_treated_as_approved(string body)
    {
        responseBody = body;
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task An_unexpected_error_status_is_surfaced_not_swallowed(int code)
    {
        status = code;
        responseBody = """{"status":"approved"}""";
        await Assert.ThrowsAsync<HttpRequestException>(Authorize);
    }

    [Fact]
    public async Task A_body_that_is_not_json_is_surfaced()
    {
        responseBody = "<html>oops</html>";
        await Assert.ThrowsAsync<JsonException>(Authorize);
    }

    private Task<AuthorizationOutcome> Authorize() =>
        new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", new Money(10m, "USD"), CancellationToken.None);

    private async Task Serve()
    {
        while (listener.IsListening)
        {
            HttpListenerContext ctx;
            try { ctx = await listener.GetContextAsync(); }
            catch { return; }

            var req = ctx.Request;
            using (var reader = new StreamReader(req.InputStream, Encoding.UTF8)) requestBody = await reader.ReadToEndAsync();
            method = req.HttpMethod;
            path = req.Url!.AbsolutePath;
            contentType = req.ContentType;

            var bytes = Encoding.UTF8.GetBytes(responseBody);
            ctx.Response.StatusCode = status;
            ctx.Response.ContentType = "application/json";
            ctx.Response.ContentLength64 = bytes.Length;
            await ctx.Response.OutputStream.WriteAsync(bytes);
            ctx.Response.Close();
        }
    }

    private static int GetFreePort()
    {
        var l = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
        l.Start();
        var port = ((IPEndPoint)l.LocalEndpoint).Port;
        l.Stop();
        return port;
    }

    public void Dispose()
    {
        client.Dispose();
        listener.Close();
    }
}
